#include "mobile_manipulator_mpc/model.hpp"

#include <array>
#include <cmath>
#include <initializer_list>
#include <stdexcept>
#include <string>

#include "wholebody_model.h"
#include "wholebody_model_links.h"

// Thin wrappers over the CasADi functions generated by scripts/generate_model.py. Every
// generated output is dense and column-major, as Eigen's default storage.
namespace mobile_manipulator_mpc
{
namespace
{
using In = std::initializer_list<const double *>;
using Out = std::initializer_list<double *>;

// Calls a generated function with stack work buffers sized by its generated SZ_* constants,
// so concurrent calls do not share memory.
template <size_t NArg, size_t NRes, size_t NIw, size_t NW, class Function>
void call(Function function, const char * name, In inputs, Out outputs)
{
  static_assert(NArg > 0 && NRes > 0, "generated function without inputs or outputs");
  std::array<const casadi_real *, NArg> arg{};
  std::array<casadi_real *, NRes> res{};
  std::array<casadi_int, NIw == 0 ? 1 : NIw> iw;
  std::array<casadi_real, NW == 0 ? 1 : NW> w;
  size_t i = 0;
  for (const double * input : inputs) arg[i++] = input;
  i = 0;
  for (double * output : outputs) res[i++] = output;
  if (function(arg.data(), res.data(), iw.data(), w.data(), 0) != 0)
    throw std::runtime_error(std::string("Generated model function failed: ") + name);
}

#define WHOLEBODY_CALL(fn, inputs, outputs) \
  call<fn##_SZ_ARG, fn##_SZ_RES, fn##_SZ_IW, fn##_SZ_W>(fn, #fn, inputs, outputs)

double checked_index(int link)
{
  if (link < 0 || link >= WHOLEBODY_MODEL_LINK_COUNT)
    throw std::out_of_range("Link index " + std::to_string(link) + " outside the model");
  return static_cast<double>(link);
}
}  // namespace

Step discrete_step(const State & x, const Control & u, double dt)
{
  Step step;
  WHOLEBODY_CALL(wholebody_step, (In{x.data(), u.data(), &dt}),
                 (Out{step.x_next.data(), step.A.data(), step.B.data()}));
  return step;
}

int link_index(const std::string & link)
{
  for (int i = 0; i < WHOLEBODY_MODEL_LINK_COUNT; ++i)
    if (link == wholebody_model_links[i]) return i;
  throw std::invalid_argument("No collision primitive on link " + link + " in the whole-body model");
}

Eigen::Isometry3d link_pose(int link, const State & x)
{
  const double index = checked_index(link);
  Eigen::Matrix4d matrix;
  WHOLEBODY_CALL(wholebody_link_pose, (In{&index, x.data()}), (Out{matrix.data()}));
  Eigen::Isometry3d pose;
  pose.matrix() = matrix;
  return pose;
}

PointJacobian point_jacobian(int link, const State & x, const Eigen::Vector3d & p_link)
{
  const double index = checked_index(link);
  PointJacobian result;
  WHOLEBODY_CALL(wholebody_point, (In{&index, x.data(), p_link.data()}),
                 (Out{result.p.data(), result.J.data()}));
  return result;
}

PanelError panel_error(const State & x, const Eigen::Isometry3d & panel_in_base)
{
  const Eigen::Vector3d p_ref = panel_in_base.translation();
  const Eigen::Matrix3d r_ref = panel_in_base.linear();
  PanelError result;
  WHOLEBODY_CALL(wholebody_panel_error, (In{x.data(), p_ref.data(), r_ref.data()}),
                 (Out{result.e.data(), result.J.data()}));
  return result;
}

double manipulability(const State & x)
{
  double m = 0.0;
  WHOLEBODY_CALL(wholebody_manipulability, (In{x.data()}), (Out{&m}));
  return m;
}

Eigen::Vector3d urdf_rpy(const Eigen::Matrix3d & r)
{
  // cos(pitch) from the first column (atan2 stays accurate near +-pi/2, where asin does not).
  const double cos_pitch = std::hypot(r(0, 0), r(1, 0));
  const double pitch = std::atan2(-r(2, 0), cos_pitch);
  if (cos_pitch < 1e-9) {
    // Gimbal lock: R = Rz(yaw) Ry(+-pi/2) with roll folded into yaw.
    return {0.0, pitch, std::atan2(-r(0, 1), r(1, 1))};
  }
  return {std::atan2(r(2, 1), r(2, 2)), pitch, std::atan2(r(1, 0), r(0, 0))};
}

Eigen::Vector3d panel_rpy_in_base(const Eigen::Matrix<double, 6, 1> & joints)
{
  static const int panel = link_index("panel");
  State x = State::Zero();
  x.tail<6>() = joints;
  return urdf_rpy(link_pose(panel, x).linear());
}
}  // namespace mobile_manipulator_mpc
